import csv, re, datetime, collections
rows=list(csv.DictReader(open('expenses.csv', newline='')))
def parsemoney(s):
    return float(re.search(r'-?\d[\d,]*\.?\d*', s).group().replace(',',''))
def parsedate(s):
    s=s.strip()
    for fmt in ('%Y-%m-%d','%m/%d/%Y','%d %b %Y','%d %B %Y'):
        try: return datetime.datetime.strptime(s,fmt).date()
        except ValueError: pass
seen=set(); data=[]
for r in rows:
    if r['id'].strip() in seen: continue
    seen.add(r['id'].strip())
    data.append(dict(id=r['id'].strip(), date=parsedate(r['date']), cat=r['category'].strip().title(), amt=parsemoney(r['amount']), status=r['status'].strip().lower()))
oct_ok=[x for x in data if x['date'].year==2026 and x['date'].month==10 and x['status']=='ok']
print(len(oct_ok), sum(x['amt'] for x in oct_ok))
by=collections.defaultdict(list)
for x in oct_ok: by[x['cat']].append(x)
for cat,items in sorted(by.items(), key=lambda kv:(-sum(i['amt'] for i in kv[1]),kv[0])):
    print(f"{cat:10} {len(items):2} {sum(i['amt'] for i in items):9.2f}")
print('excluded oct void', [(x['id'],x['date'].isoformat(),x['cat'],f"{x['amt']:.2f}") for x in data if x['date'].year==2026 and x['date'].month==10 and x['status']!='ok'])
print('outside oct', [(x['id'],x['date'].isoformat(),x['status']) for x in data if not (x['date'].year==2026 and x['date'].month==10)])
print('min max dates', min(x['date'] for x in oct_ok), max(x['date'] for x in oct_ok))
print('avg', sum(x['amt'] for x in oct_ok)/len(oct_ok))
PY", "description": "Compute category totals and exclusion counts"}

