import re, csv, datetime
text=open('report.md').read()
report_ids=set(re.findall(r'\| [A-Z][a-z]{2} \d{1,2}, 2026 \| (\d+) \|',text))
def pdate(s):
    for f in ('%Y-%m-%d','%m/%d/%Y','%d %b %Y','%d %B %Y'):
        try:return datetime.datetime.strptime(s.strip(),f).date()
        except:pass
seen=set(); exp=set(); allrows=0
for r in csv.DictReader(open('expenses.csv')):
    allrows+=1
    if r['id'] in seen: continue
    seen.add(r['id'])
    d=pdate(r['date'])
    if d.year==2026 and d.month==10 and r['status'].strip().lower()=='ok': exp.add(r['id'])
print('expected',len(exp),'reported',len(report_ids))
print('missing',sorted(exp-report_ids),'extra',sorted(report_ids-exp))
print('source rows',allrows,'unique',len(seen))
PY", "description": "Cross-check reported IDs against expected October transactions"}

